   "body": "**已確認外觀：** 淺金色頭髮在風中飛散，皮膚極白、日光下透出淡粉血色，眼睛近乎無色卻有極淡的藍。穿紅、藍兩色的絲質雜色衣；身形纖細，外貌只鎖定為年輕而難以判讀的宮廷弄臣。\n\n**人物設定：** 堡中流言稱他無法忍受日光，第七章卻讓蜚滋在戶外見到他。他以看似胡言的音節反覆傳遞訊息，隨即又能清楚地反駁蜚滋把他當作迷路的可憐人。本設定不解釋訊息含義，也不延伸其身分或動機。\n\n**首次關聯：** 第 007 章〈一項任務〉。",
