   "title": "莫莉・小花束",
   "desc": "第六章在燭店重逢的少女；以重新取回的本名與實作蜂蠟燭的手藝，成為蜚滋短暫能看見的城裡生活。",
   "body": "**已確認外觀：** 深色眼睛、濃密深褐髮披至肩頭；身形嬌小。穿承自大人的暗紅羊毛長裙、米白亞麻上衣與磨舊的靴子，提著裝有蜂蠟燭與藥草的小籃。\n\n**人物設定：** 她曾被叫作「小花臉」，現在在父親的燭店工作，熟悉蜂蠟、香料與草藥。表面克制而敏銳，對被外號命名仍帶著防備；母親留下的木牘使她知道自己的本名是「莫莉・小花束」。本設定只鎖定第六章的城內重逢狀態，不延伸後續關係。\n\n**首次關聯：** 第 006 章〈駿騎的影子〉。",
