   "title": "無色粉末紙包",
   "desc": "切德交給蜚滋的細白粉末與薄紙包；它不是命令本身，而是把判斷與後果交到孩子手裡的可能。",
   "body": "**已確認外觀：** 極薄的上好白紙折成小包，內有細如浮塵的白色粉末；可搭配折起的油紙、帶蓋小陶盤與遮住口鼻的布。畫面中不配置文字、標記或瓶罐。\n\n**敘事功能：** 切德為蜚滋前往潔宜灣準備的無色無味粉末。任務的條件不是立即動手，而是蒐集證據並自行決定是否使用它；因此紙包承載的是不確定的責任，而非既定的處決。\n\n**首次關聯：** 第 007 章〈一項任務〉。",
