   "body": "**已確認外觀：** 中型年幼獵犬，深栗色短毛帶黑色陰影、垂耳、寬鼻口與深色眼睛；僅佩戴磨舊皮項圈。設定稿將牠畫成健康、主動而非兇猛的夥伴。\n\n**人物設定：** 大鼻子是蜚滋最早能共享感官與夢境的同伴。博瑞屈把牠帶走不是出於對狗的惡意，而是恐懼蜚滋被原智吞沒；因此牠在後續回憶或象徵畫面中，同時代表被奪走的親密與不需證明血統的歸屬。不得在未讀情節中補上牠後來的遭遇。",
