   "title": "黃銅手環設定稿 (Brass Bracelet)",
   "desc": "切德交給蜚滋的簡單黃銅手環；不昂貴、不華麗，卻證明密室與課程不是一場夢。",
   "body": "**已確認外觀：** 無裝飾、略有氧化的窄幅開口黃銅手環，尺寸適合孩子手腕。切德提醒它可能把手腕染綠，因此質感應是日常金屬，而不是金飾。\n\n**敘事功能：** 第四章結尾，蜚滋找不到密門，手環便成了他對切德與那個夜晚的唯一實物證據。它適合作為暖燈下的小反光，象徵秘密既已存在、又無從對外證明。",
