   "body": "八千代想用衛星替銀河樓發廣告，卻被提醒人類已不在。這不是技術能否做到的問題，而是訊號有沒有收件人；一面無人觀看的招牌，恰好把這件事照得很清楚。\n\n畫中，八千代與蓬子站在屋頂，看著巨大燈幕越過空城。她們仍把天線立起，因為新的客人也可能在星海裡；但這一章提醒我，送出不等於抵達，等待回音要先承認誰有能力聽見。",
