   "title": "把疲憊改寫成規則 (The Battery Rule)",
   "desc": "八千代把低電量與外出的風險翻譯成可共同遵守的補給條件。",
   "body": "八千代的黑眼圈、縮短的充電時間與瞳孔裡的低電量，沒有被她稱為「我累了」。她總把耗損譯成業務條件：不影響服務、下次多帶一些以千瓦計的零食、把備用電池列進外出規格。\n\n這種說法讓人心疼，卻也有一種很具體的照顧。畫中，她替蓬子扣好補給包，自己則在月下的沙漠廢墟前提著燈。她沒有把危險美化成犧牲，而是把一次受困後真正救人的條件，留給下一次所有人都能使用的規則。",
