   "title": "有名字的一餐 (A Meal with a Name)",
   "desc": "必須取用生命才能活下去時，命名、感謝與敬意使那一餐不淪為無名的資源化。",
   "body": "努德爾頓先被取了名字，才被端上餐桌。第四章讓我修正了「危機被轉成資源」的簡化讀法：捕食確實發生，但八千代與蓬子以感謝與敬意說著「いただきます／ごちそうさま」，承認眼前這條命曾經活著。\n\n畫中兩人合掌，窗外月光裡留著巨大沙生物的剪影；桌上沒有展示獵物的暴力，只留下完成一餐所需的莊重。銀河樓的待客規格在這裡被擴寫成待命之道：生存未必能不奪取，仍可以不把被取用者降成無名材料。",
