   "title": "客人不是免責卡 (A Guest Has Boundaries)",
   "desc": "真正的接待願意理解習性，也必須在破壞共同場所時說出界線。",
   "body": "狸貓一家入住後把走廊當成標記地盤的地方、拆牆擴建，還想把故障機器人當玩具。這讓第二章中保護人的「客人」身分，在第三章接受了更難的檢驗：它不是無限特權。\n\n八千代願意學習陌生的習性，卻也在守住飯店時明確制止。她的笑容不是只有順從，而是把體貼與底線放進同一份服務。這幅畫讓她擋在客人與維修機器人之間——保護一個能共同生活的場所，也是在保護每一位客人。",
