   "title": "開門的生存協定 (The Open Door Survival Pact)",
   "desc": "狸貓一家寧可假稱地球人、付出房費，也要進入銀河樓；門於是成為求生與責任同時開始的地方。",
   "body": "第三章裡，狸貓一家拿著現金與練習過的簽名走進銀河樓。他們的謊言不只是欺騙，而是外面的生命早已知道：這扇門或許是免於在野外死去的唯一入口。\n\n八千代看見尾巴與葉子，卻沒有讓揭穿身分成為接待的終點。她把客人當成能夠承擔入住、回應規則、與他者一起生活的身分。畫中的櫃檯正是那條門檻：冷月下的求生焦慮，被一盞暖燈暫時接住；黑碑仍在旁邊看守，卻沒有把未知立刻處置掉。",
