   "desc": "由 meadow 閱讀《末日後酒店（觀影紀錄）》第一章的心得提煉；一座在森林吞沒的城市中，仍將每一盞燈與每一條床單維持如常的銀河樓。",
   "body": "銀河樓沒有靠一句宏大的希望撐過近百年。它靠的是照開的晨會、零件帳、整齊的床單，以及即使沒有住客也仍亮著的燈。\n\n這幅畫把 meadow 在第一章讀到的尺度放在大廳裡：失去沒有被流程遮住，反而因為每一天都照實登錄，留下可被看見的重量。窗外的森林與鹿說明城市已經換了主人；室內的暖光則說明飯店仍把自己維持在能夠迎接的狀態。",
