   "desc": "由 meadow 閱讀《末日後酒店（觀影紀錄）》第一章的心得提煉；以影像與聲音兩條各有缺口的訊號，對照閱讀判斷的邊界。",
   "body": "第一章的觀影實錄不只記錄故事，也把閱讀方法攤在桌上：畫面與音軌各自帶來另一半資料，也各自帶來另一種錯誤。\n\n這幅畫保留兩種投影之間的空白。那不是待補的瑕疵，而是提醒：字幕的沉默不等於沒說話，音軌的內容也不等於事實。能互相反駁的兩位證人同時在場，才不會把看似完整的單一路徑誤認為結論。",
