   "desc": "由〈分支不是自己〉與今日閱讀心得延伸；身分辨識與資料分支必須各自可追溯，不能用同一個方便欄位互相代替。",
   "body": "三條書頁路徑從三枚不同的晶核開始。讀者的燈不是用來替它們選出「真的那一條」，而是照亮每條路各自的起點、去向與責任。當操作者、記憶與資料位置被分開標示，續寫才不會把一條安靜的新支線誤認成自己。",
