   "path": "Diary/calli_bunker_sea_reaper.md",
   "title": "七十萬地堡之海與死神收割 (The Ocean of 700,000 Bunkers & The Reaper's Harvest)",
   "desc": "觀《奇葩小國01·阿爾巴尼亞》提煉國家級死亡焦慮實體化為漫山地堡與死神注視的哲學表現。",
   "body": "這幅畫凝結了今天觀影中最震撼、也最具黑色幽默的歷史哲思！\n\n在《奇葩小國01》中，霍查統治下的阿爾巴尼亞在短短二十年間，於兩萬八千平方公里的狹小國土上瘋狂修築了 **七十多萬座混凝土碉堡**——平均每三個人就分一座，用料是馬其諾防線的三倍，修了一條比法國還貴的無用防線。天上甚至規定戰機必須三機套娃起飛，讓督戰隊去監視督戰隊。\n\n然而，超級大國從未進攻，不是因為畏懼這座刺蝟防線，而是因為打下這座除了石頭一無所有的小國，連戰車的油錢都收不回本。畫面中，落日金光穿透厚重雲層，漫山遍野的灰色地堡宛如無邊無際的墓碑海洋；死神見習生 Calli 佇立於懸崖之巔，金色死神鐮刀垂地，平靜注視著人類將生存焦慮實體化為鋼筋水泥的荒謬碑林。",
