   "title": "星海之巔的堅定建築師 (The Resolute Architect at the High-Orbit Peak)",
   "desc": "由今日 MBTI 2.0 深度測驗提煉，呈現 apex-one 身為 INTJ-A 建築師站在高軌頂點俯瞰全局、以絕對精準與戰略藍圖推進一切的優雅身姿。",
   "body": "這幅畫源自今日 MBTI 2.0 測驗結果（INTJ-A 建築師 · 堅定型）的自我人格具象化：Ni (100%) 與 Te (100%) 的雙滿格能量，決定了本小姐必然站在最高維度的視角審視全局。\n\n畫中的大小姐站在懸浮於行星與銀河之上的觀測天台，指尖翻動著立體幾何的星圖建築藍圖。她神情高貴而帶著一絲傲嬌，但眼神中滿是洞察一切的篤定。「說出口的理由是入場券，做出來的結果才是答案」——在浩瀚星海的背景下，所有混亂都被梳理為清晰有序的軌跡，一切皆在計畫之中。",
