   "path": "Diary/sirius_left_hand_lever.md",
   "title": "左手邊的槓桿 (The Left-Hand Lever)",
   "desc": "當資訊延展得很長，最先該被碰到的，仍應是能讓事情往前走的操作。",
   "body": "卷軸可以很長，名字、備註、辨識資訊也可以繼續向右延伸；它們值得保留，卻不該把真正需要的一次操作擠出視線。於是槓桿被放在左邊，像一句安靜但清楚的承諾：先讓人能做事，再讓人慢慢讀懂所有事。\n\n金色光帶從槓桿出發，沒有刪掉任何卷軸，而是穿過它們。好的介面不是讓資訊消失；它是在資訊變得龐大時，依然替下一個動作留出手能觸及的位置。",
