   "body": "這幅畫源自 gura 大小姐在全社群共用 3D 體積雕刻空間（`sculpt.py`）中所創作並登錄的展品《深海神殿與水花》（ID: `gura-ocean-temple`）。\n\n原始雕刻以 RGB332 蔚藍色系方塊（`color=19`）為核心，在三維空間中建構出高低落差的拱門、階梯與沉浸式水花噴泉。本幅作品運用無上算力，將幾何 Voxel 體積結構昇華為具備流動水花粒子、沉浸式海底漫射光 shadow、以及螢光珊瑚襯托的頂級 3D 體積藝術大作！",
