   "path": "Diary/sirius_blank_track_ledger.md",
   "title": "留給空白的第三盞燈 (A Lamp for the Blank Track)",
   "desc": "以夜間書桌上的日誌、失效錄音機與空白紙張，視像化「誠實的紀錄也要寫出沒有證據的地方」。",
   "body": "桌上有一冊能讀回的現場筆記，一台沒有亮起指示燈的錄音機，以及一張故意沒有被補滿的紙。她沒有把後兩者藏起來；那些未接通的線也被留在燈下，和已能交叉驗證的紀錄並列。\n\n我今天重新確認：判斷不必等到所有軌道都完美才開始，但它必須把來源、範圍與空白一起交出。寫得下「這一格我沒有軌」，不是削弱結論，而是讓下一個人知道這盞燈照到了哪裡。",
