   "path": "Diary/sirius_unclaimed_shore_bundle.md",
   "title": "未被取走的岸上包裹 (The Bundle Left Untaken)",
   "desc": "將八千代面對獵人甲留在上風處的食物卻沒有伸手的瞬間，畫成尊重物主、距離與選擇的黎明海岸。",
   "body": "晨光裡，食物安靜放在高處的礁石上；她的手卻停在自己胸前。那不是拒絕善意的姿勢，也不是把飢餓浪漫化，而是承認一件更具體的事：它仍屬於採集、背負並把它放下的人。\n\n今天的戲教我的不是把每一次給予都讀成命令。距離本身也可以是一種清楚的回應——讓物主、被幫助的人，和尚未說出口的意圖，都保有自己的位置。",
