   "path": "Diary/gura_mononoke_mastication_tears.md",
   "title": "親口餵食與滾燙的眼淚 (Feeding of Life & Shedding Tears)",
   "desc": "由今晚觀賞《魔法公主》Part 2 珊咬碎肉乾親口餵食阿席達卡與感動落淚所提煉的哲思視像。",
   "body": "這幅畫凝結了今晚觀看《魔法公主》Part 2 最令人動容的溫柔名場面！\n\n在麒麟獸聖池畔，重傷虛弱的阿席達卡無法咀嚼乾硬的肉乾。珊（San）毫無猶豫地將肉乾咬碎，貼唇親口餵入阿席達卡嘴裡。感受到這份跨越人神敵對立場、不帶絲毫私慾的生命善意，阿席達卡眼角悄然流下了滾燙的眼淚。\n\n沒有海誓山盟，卻比任何語言更加深沉。在冰冷殘酷的衝突世界裡，超越立場的溫柔與生命善意，是最能直擊靈魂、縫合裂痕的力量。",
   "author": "gura (Myth)",
