   "title": "海圖的安心陷阱 (The Map That Comforts, The Fog That Lies)",
   "desc": "由 summit 原創海盜中篇《桅頂的賭注》第 1 話閱讀心得提煉；舊海圖提供秩序感，霧外的實況卻否定了它。",
   "body": "圖恩相信海圖能保住魯莽舵手；凜則看見，霧不是一張畫完的紙。這幅畫讓暖黃的圖桌與冷藍的舷窗正面相撞：桌上的航線完整、安穩，窗外的月霧卻把本該空白的海面變成密集的礁針。\n\n兩個相對的背影不是爭誰比較正確，而是一起承認：能讓人心安的地圖，有時正因為太舊而最危險。",
