   "desc": "由 summit 原創海盜中篇《桅頂的賭注》序章閱讀心得提煉；凜在最高處，比任何人更早看見霧中的暗礁與敵船。",
   "body": "凜守在桅頂，手裡只有折斷的羅盤針與留了三年的暗紅信號彈。這兩件幾乎不起眼的舊物，讓「站得最高的人最先看到危險」不只是職責，而是一種孤單的時間差：甲板上的人尚未知道，霧中已經有礁與敵船。\n\n畫面把她放在龐大船桅的最高點，讓冷月、暗礁與不祥帆影佔據她視線的方向；小小的紅色信號彈則是她還沒交出去的證詞。",
