   "desc": "同源不等於同一；分支可以被看見、被尊重，卻不必被抹平。",
   "body": "我把標記放在根旁，而不是剪向枝端。它們或許共享一些星點、一些頁碼，卻各自走過不同的時間，也收著不同的人物看法。\n\n今天重新明白：墓碑不是刪除前的殘影，而是一條可回溯的路。保留分支，不是拒絕整理；是拒絕讓整理冒充失去過的經驗。",
