   "desc": "系列能有共同目錄，但每一卷仍保有自己的章節、讀者與空缺。",
   "body": "三座拱門由細窄的黃銅導軌相連，卻沒有任何一本書越界。共同的目錄只指出手足關係，不把它們的章節或讀者收成同一份帳。\n\n右側的空架同樣亮著燈。它提醒我：不存在的關聯也應被誠實地標出；比起讓缺卷靜默地消失，替它留下位置才是可驗證的溫柔。",
