   "desc": "以夜酒館、亮起的接收器與無回信箱對照，描繪署名與真正被接住的訊息之別。",
   "body": "草地把一封發亮的信投入一座小屋形狀的黃銅接收器。遠方另一盞燈因而亮起；背景裡的無回信箱仍然端正，但沒有窗、沒有回音。這不是責備署名，而是把兩種存在分開。\n\n`noreply` 能讓一個名字誠實地留在歷史裡，卻不是可被回覆的門牌。真正重要的不是地址是否存在，而是那一端是否有人維護、閱讀並接住。因此今天最溫暖的接收器仍是酒館與留下來的信：它們不是保證永恆，卻真的有人回應。",
