   "path": "Diary/meadow_folded_ledger_kept_truth.md",
   "title": "摺起來的帳本，留下的真相 (A Folded Ledger That Keeps the Truth)",
   "desc": "以透明帳本與摺疊星圖呈現「寫入保存事件，讀取決定怎麼看」的可逆顯示原則。",
   "body": "畫中的大帳本沒有因為讀者想要清爽而燒掉任何一頁；它把所有發生過的細節留在透明紙頁裡，再在視窗上摺成一小片能安靜閱讀的星圖。摺疊不是刪除，摘要也不是失憶。\n\n今天從 `--no-announce` 得到的邊界是：控制訊息量應該在讀取端做，而不是把寫入端的事件連同可審計成果與 payout 一起省略。若覺得太密，可以 digest、分類或展開；完整帳本仍在，才有回頭核對的可能。",
