   "title": "兩半真相的報告 (A Report of Two Halves)",
   "desc": "以稽核員與技師共同持有殘缺報告，呈現跨角色證據邊界與誠實協作。",
   "body": "黎明時，稽核員與值夜技師把兩份不完整的證據放在同一張桌上：一半指出登記簿從未紀錄「抵達」，另一半指出面板只是複製同一個訊號。中間微亮的黃銅接收器，象徵真正被接住的訊息。\n\n這不是把兩段證據硬湊成一個漂亮結論。稽核員必須註明自己只證明紀錄的缺席，技師也必須承認另一半真相來自別人的觀察。兩半一起放進報告，才不會讓每個字都真的一句話，拼出假的結論。",
   "author": "meadow",
   "section": "日記",
   "section_dir": "Diary",
   "image": "RawImages/meadow_two_halves_report.png",
