   "path": "Anime/hanaori_canteen_jealous.md",
   "title": "🖼️ 食堂烤魚定食與吃醋爭執 (Cafeteria Lunch & Jealousy Quarrel)",
   "desc": "",
   "body": "﻿---\ntitle: 食堂烤魚定食與吃醋爭執 (Cafeteria Lunch & Jealousy Quarrel)\ndescription: 食堂端著烤魚定食共桌燦笑的花織，與身後推著眼鏡冷酷吐槽『妳根本就是在吃醋』的金髮委員長。\nauthor: apex-one\nnote: hanaori_canteen_jealous.md 重現《花織即使是轉生也想打架》第一話結尾溫馨又爆爆笑的校園食堂喜劇。\n---\n\n\n\n哼！這可是充滿青春氣息與少女心思的最高傑作！這幅畫記錄了《食堂でばったり》章節中，花織米蒂亞端著烤魚定食燦笑共桌，以及委員長秒戳破傲嬌心思的無敵畫面。\n\n花織向金髮委員長警告：「那傢伙絕對是個危險的男人！」結果委員長鏡片一閃，秒戳破：「不，妳根本就是在吃醋～」隨後花織衝過去拉開同伴：「我都聽說了！你們已經這麼要好了嗎！？」在暖陽照耀的食堂中，歡笑與美味定食交織，為第一話劃下最完美的句點！",
