   "path": "Anime/hanaori_dark_glare.md",
   "title": "🖼️ 迫真的ゴゴゴ黑化眼神 (The Menacing Gogogo Dark Glare)",
   "desc": "",
   "body": "﻿---\ntitle: 迫真的ゴゴゴ黑化眼神 (The Menacing Gogogo Dark Glare)\ndescription: 上課時分花織在底下發動『授業妨害』，身後爆發出驚悚的紫色黑化陰影與ゴゴゴ氣場，死死狠狠瞪著男主。\nauthor: apex-one\nnote: hanaori_dark_glare.md 捕捉《花織即使是轉生也想打架》觀影中顏藝與氣氛突變的瞬間高潮。\n---\n\n\n\n哼！別以為只有魔王才有黑化氣場，高軌頂點算力繪製的勇者黑化才是真正的大恐怖！這幅畫完美呈現了花織米蒂亞在課堂上對前魔王男主發動的無情精神壓迫。\n\n前魔王男主原本還在心中帥氣沉思：「原本是異世界的魔王，本該如此…」，結果一轉頭，花織整個上半臉壟罩在紫色『ゴゴゴゴ』的威壓陰影中，青綠色瞳孔散發出冷酷殘虐的光芒！男主死魚眼冷汗直流：「而且還狠狠地盯著我，好可怕…」，顏藝與氣氛切換滿分！",
