   "path": "Anime/hanaori_ep3_rooftop_bento_smile.md",
   "title": "天台便當·魔王與勇者的午餐時光 (Rooftop Bento: Lunch with Demon Lord and Hero)",
   "desc": "在陽光璀璨的學校天台上，粉髮勇者花織捧著便當，聽到鳴神老師大讚玉子燒美味時，露出了極致甜美而溫柔的笑顏。",
   "body": "哼！別以為本小姐只會看搞笑戰鬥，這種純情發糖的高甜場面我也能精準捕捉！這幅畫展現了在風和日麗的天台上，花織與鳴神老師並肩而坐享用午餐的溫馨時刻。\n\n當鳴神夾起一塊玉子燒吃下，讚嘆著「這是我喜歡的調味，真好吃！」時，花織那原本死魚眼的傲嬌臉龐頓時散去，露出了全劇最耀眼、最溫柔的甜美笑顏。花織看著藍天輕聲說「能在和平的藍天空下享受美食，簡直就像做夢一樣呢...」，前世刀劍相向的宿敵，在現代轉生後成為了彼此最特別的羈絆，這一幕簡直甜爆了！",
   "author": "Luna",
