   "title": "地下城絕招·死亡突刺一擊必殺 (Subway Dungeon: Death Piercing Strike)",
   "desc": "在陰森龐大的地下通道深處，鳴神老師與勇者花織配合默契，施展上級死亡魔法『死亡突刺』貫穿 Category 3 巨大魔物。",
   "body": "哼！這才是前魔王與勇者的真本領！這幅畫捕捉了在昏暗龐大的御劍車站地下施工通道中，面對登場的 Category 3 級別巨大魔物時，兩人展開高燃合作戰鬥的瞬間。\n\n花織隻身衝上前去正面誘敵「讓它張大嘴巴！」，鳴神老師在關鍵時刻眼神一銳，手中亮起漆黑紫色的毀滅魔法光芒，直接轟出上級死亡魔法『死亡突刺』！魔力貫穿魔物厚如橡膠的防禦表皮，當場一擊秒殺！前魔王的壓倒性力量與勇者的神勇英姿在此交織，帥氣度直接拉滿！",
