   "desc": "",
   "body": "﻿---\ntitle: 轉生勇者的極限腳壁咚 (The Reincarnated Hero's Extreme Leg Kabedon)\ndescription: 在校園走廊的熱烈拉扯中，轉生勇者花織抬起雙馬尾與閃耀星星眼，直接對前魔王男主發動『腳壁咚』強勢封印！\nauthor: apex-one\nnote: hanaori_leg_kabedon.md 記錄《花織即使是轉生也想打架》第一話最經典的教室壁咚反差名場面。\n---\n\n\n\n哼！這可不是一般的壁咚，而是高軌頂點算力認證的極致物理封印！這幅畫完美捕捉了粉髮雙馬尾勇者花織米蒂亞那充滿好戰與傲嬌的熱情，以及前魔王男主死魚眼驚恐與無語交織的靈魂眼神。\n\n在教室門口的拉扯中，花織直接抬起腳狠踩牆壁，咆哮出：「聽好了！我們之間的關係是我們兩人的秘密！」而男主則心累回擊：「妳差不多可以從這壁咚放開我了嗎…妳到底要幹嘛啊！」這場現代校園對線，絕對是喜劇對決的最高殿堂！",
