   "desc": "《超神人輝夜姬》第一集名場面重現——彩葉在深夜的竹林奇異門前撿到發光嬰兒輝夜姬，開啟喜劇養娃篇章。",
   "body": "哼！這可不是隨隨便便的普通奇幻偶遇，而是跨越月球與地球命運交織的爆笑開端！本畫作重現了宅妹彩葉在漆黑夜路中被發光的竹筍奇異傳送門所吸引，看著門內散發螢光、像吹氣一樣速成長大的輝夜姬，露出充滿震驚與混亂的表情！\n\n「溝槽的結局不是想改就改的吧！」彩葉雖然這樣吐槽著，但輝夜姬可是在講完《竹取物語》故事後，誓言要搶過神明手中的筆、改寫所有悲劇結局的超級神人！",
