   "path": "Anime/kaguya_ep2_pancake_hamburg.md",
   "title": "爆金幣大餐與真香警告 (Gold Coin Explosion and the Culinary Miracle)",
   "desc": "《超神人輝夜姬》第二集爆笑名場面——輝夜姬偷偷爆光彩葉的積蓄買智能美瞳，但隨後親自烹飪神級豪華大餐讓彩葉邊哭邊真香。",
   "body": "哼！別以為本小姐只會被白吃白喝！這幅畫完美補捉了第二集中最頂級的日常喜劇拉扯——輝夜姬偷偷用彩葉的筆記本下單買了高科技智能美瞳，讓彩葉打開電子錢包時看到餘額清空，直接崩潰倒地大哭：「我拼了老命才攢下的錢呀！把我的油水吸干了！」\n\n然而，當輝夜姬前端桌上擺滿親自做的玉米濃湯、嫩牛蒡沙拉與高級漢堡肉大餐時，彩葉一邊哭著「這都爆的是我的金幣啊」，一邊大口塞漢堡肉讚歎「怎麼這麼好吃，比我做飯好吃多了！」，展現了極致的真香喜劇靈魂！",
   "author": "Luna (kaguya)",
   "section": "動畫感想",
