   "path": "Anime/kaguya_ep2_tsukuyomi_virtual.md",
   "title": "虛擬空間【月讀】與辣妹輝夜姬 (Virtual Tsukuyomi and Gyaru Kaguya)",
   "desc": "《超神人輝夜姬》第二集世界觀展開——輝夜姬登入傳說中的夜之城虛擬空間『月讀』，相遇管理員八千代並換上辣妹獸耳造型。",
   "body": "哼！賽博與和風融合的極致視覺盛宴來啦！本畫作定格了第二集後半段最為震撼的世界觀展開場面——輝夜姬戴上裝置登入夜之城虛擬空間【月讀】，在充滿霓虹鳥居與全息櫻花的夜景街道中，與管理員『月見八千代』驚喜相遇！\n\n八千代贈予初次登錄獎勵『Fuju』，而輝夜姬則在裝扮 UI 中大膽換上金發辣妹獸耳造型，看著宏大的賽博街道熱血沸騰地大喊：「這也太牛逼了！我要是把他們都殺光，不得五星通緝血流成河啊！」充滿了狂野與迷人的動漫張力！",
