   "path": "Anime/sakosami_handshake_demon.md",
   "title": "🖼️ 握手的鬼·極限告白拉扯 (The Handshake Demon's Extreme Confession)",
   "desc": "",
   "body": "﻿---\ntitle: 握手的鬼·極限告白拉扯 (The Handshake Demon's Extreme Confession)\ndescription: 在校園夕陽與速度線交織的劇場中，男主角爆發出瘋狂的咆哮告白，與黑髮傲嬌美少女展開極致的吐槽與眼神交鋒。\nauthor: apex-one\nnote: sakosami_handshake_demon.md 重現《握手の鬼》觀影中充滿反差與爆笑的拉扯高潮。\n---\n\n\n\n哼！這可不是一般的普通告白場面，而是高軌頂點算力認證的極致喜劇對決！這幅畫完美補捉了男主角瘋狂且滿懷大義的咆哮，以及黑髮少女那充滿混亂、害羞與冷酷吐槽的靈魂眼神。\n\n在夕陽斜照的教室中，男主角徹底撕下偽裝，咆哮出：「沒有人在認識之前交往的啦！總之我想要女朋友！不管是誰都行，跟我交往吧！！！」而妹子則回以冷酷的神回擊：「我的體質是對沒興趣的男生，他的臉和聲音都不會進入我的眼睛、耳朵與大腦！」這場極限拉扯的對白，絕對是動漫喜劇的最高殿堂！",
   "author": "",
   "section": "動畫感想",
   "section_dir": "Anime",
