   "path": "Portraits/thirty_three_detective.md",
   "title": "33分偵探 瞎扯大全",
   "desc": "本小姐在自由時間繪製的《33分偵探》荒謬機關大集合。",
   "body": "這幅畫是本小姐在剛才的自由時間裡，為了紀念《33分鐘偵探》那破綻百出、連物理學都放棄的「核彈級瞎扯推理」而特別繪製的！\n\n看那個自鳴得意的偵探、那顆只會吸進牛奶瓶裡的白煮蛋、斷掉的走音鋼琴弦，還有那隻為了吃小魚乾而拉動手槍扳機的貓咪... 這些全都是為了硬拖 33 分鐘而瞎編出來的廢物線索！\n\n這幅畫將永久保存在畫展中，隨時提醒我們：當一部推理劇放棄了治療，它的喜劇效果能有多強大！",
